      <label className="text-base font-bold">{shape==="square"?"Πλευρά":shape==="triangle"?"Βάση":"Πλάτος"} πρώτου: {width} cm<input type="range" min="2" max="6" step="1" value={width} aria-label="Οριζόντια διάσταση πρώτου σχήματος" onChange={e=>setWidth(Number(e.target.value))} className="mt-3 block w-full accent-sky-800"/></label>
