import {useId,useMemo,useState} from "react";
import {Move,RotateCcw,Sparkles} from "lucide-react";
import {MathText} from "@/components/MathText";
import {buildUnitCircleModel,unitCircleAngleFromPoint,UNIT_CIRCLE_ANGLES} from "./unitCircleModel";
const decimal=x=>x.toLocaleString("el-GR",{maximumFractionDigits:4});
const latexDecimal=x=>decimal(x).replace(",","{,}");
const sign=x=>x===null?"δεν ορίζεται":x>0?"θετικό":x<0?"αρνητικό":"μηδέν";
function CircleDrawing({model,changeAngle,projections}){
  const titleId=useId(),cx=340,cy=250,r=175,px=cx+r*model.x,py=cy-r*model.y;
  const angle=model.degrees*Math.PI/180,arcX=cx+45*model.x,arcY=cy-45*model.y;
  const move=e=>{const svg=e.currentTarget.ownerSVGElement,matrix=svg?.getScreenCTM();if(!matrix)return;const p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const q=p.matrixTransform(matrix.inverse());const a=unitCircleAngleFromPoint({x:(q.x-cx)/r,y:(cy-q.y)/r});if(a!==null)changeAngle(a);};
  const release=e=>{if(e.currentTarget.hasPointerCapture(e.pointerId))e.currentTarget.releasePointerCapture(e.pointerId);};
  const keyMove=e=>{const delta={ArrowRight:1,ArrowUp:1,ArrowLeft:-1,ArrowDown:-1}[e.key];if(delta){e.preventDefault();changeAngle(Math.max(0,Math.min(180,model.degrees+delta)));}else if(e.key==="Home"||e.key==="End"){e.preventDefault();changeAngle(e.key==="Home"?0:180);}};
  const corner=model.x>0?-9:9;
  return <div className="overflow-x-auto rounded-xl border border-indigo-200 bg-white p-2 [--uc-cos:#1f4e7b] [--uc-sin:#0f766e] [--uc-point:#b45309] dark:border-indigo-500/30 dark:bg-slate-950 dark:[--uc-cos:#7dd3fc] dark:[--uc-sin:#5eead4] dark:[--uc-point:#fbbf24]">
    <svg viewBox="0 0 680 465" className="min-w-[500px] w-full" role="group" aria-labelledby={titleId}><title id={titleId}>Μοναδιαίος κύκλος με γωνία ω={model.degrees}°. Το Μ έχει τετμημένη συνω={decimal(model.x)} και τεταγμένη ημω={decimal(model.y)}.</title>
      <circle cx={cx} cy={cy} r={r} fill="none" stroke="currentColor" strokeWidth="1.5" opacity=".18" strokeDasharray="6 5"/>
      <path d={`M ${cx+r} ${cy} A ${r} ${r} 0 0 0 ${cx-r} ${cy}`} fill="none" stroke="currentColor" strokeWidth="2.5" opacity=".7"/>
      <g stroke="currentColor" strokeWidth="1.8" opacity=".65"><line x1="100" y1={cy} x2="580" y2={cy}/><path d="M580 250l-10 -5v10z" fill="currentColor"/><line x1={cx} y1="445" x2={cx} y2="35"/><path d="M340 35l-5 10h10z" fill="currentColor"/></g>
      <g fill="currentColor" fontSize="17"><text x="589" y="256">x</text><text x="351" y="40">y</text><text x={cx+12} y={cy+22}>Ο</text><text x={cx+r} y={cy+23} textAnchor="middle">1</text><text x={cx-r} y={cy+23} textAnchor="middle">−1</text><text x={cx+12} y={cy-r+5}>1</text><text x="542" y="232">0°</text><text x="108" y="232">180°</text><text x={cx-18} y="58">90°</text></g>
      {projections&&<><polygon points={`${cx},${cy} ${px},${cy} ${px},${py}`} fill="var(--uc-sin)" fillOpacity=".06"/><line x1={px} y1={py} x2={px} y2={cy} stroke="var(--uc-cos)" strokeWidth="2" strokeDasharray="6 5"/><line x1={px} y1={py} x2={cx} y2={py} stroke="var(--uc-sin)" strokeWidth="2" strokeDasharray="6 5"/><line x1={cx} y1={cy} x2={px} y2={cy} stroke="var(--uc-cos)" strokeWidth="5"/><line x1={cx} y1={cy} x2={cx} y2={py} stroke="var(--uc-sin)" strokeWidth="5"/>
      {model.degrees!==0&&model.degrees!==90&&model.degrees!==180&&<path d={`M ${px+corner} ${cy} v -9 h ${-corner}`} fill="none" stroke="currentColor" strokeWidth="1.4" opacity=".7"/>}</>}
      <line x1={cx} y1={cy} x2={px} y2={py} stroke="var(--uc-point)" strokeWidth="3"/>
      {model.degrees>0&&<path d={`M ${cx+45} ${cy} A 45 45 0 0 0 ${arcX} ${arcY}`} fill="none" stroke="var(--uc-point)" strokeWidth="2.5"/>}<text x={cx+68*Math.cos(angle/2)} y={cy-68*Math.sin(angle/2)} textAnchor="middle" fontSize="18" fontWeight="800" fill="var(--uc-point)">ω</text>
      <g role="button" aria-label="Μετακίνηση του Μ με τα βέλη" tabIndex="0" onKeyDown={keyMove} onPointerDown={e=>{e.preventDefault();e.currentTarget.focus();e.currentTarget.setPointerCapture(e.pointerId);move(e);}} onPointerMove={e=>{if(e.currentTarget.hasPointerCapture(e.pointerId))move(e);}} onPointerUp={release} onPointerCancel={release} className="group cursor-grab touch-none outline-none"><circle cx={px} cy={py} r="23" fill="transparent"/><circle cx={px} cy={py} r="7" fill="var(--uc-point)" strokeWidth="3" className="stroke-white group-focus:stroke-indigo-500 dark:stroke-slate-100"/><text x={px+(model.x>=0?14:-14)} y={py-13} textAnchor={model.x>=0?"start":"end"} fontSize="20" fontWeight="800" fill="var(--uc-point)">Μ</text></g>
      <text x="340" y="455" textAnchor="middle" fontSize="16" fill="currentColor">ΟΜ = 1 · ω = {model.degrees}° · μέτρηση από τον θετικό ημιάξονα x</text>
    </svg>
  </div>;
}
export function UnitCircleExplorer(){
  const headingId=useId();const [degrees,setDegrees]=useState(120),[projections,setProjections]=useState(true);
  const model=useMemo(()=>buildUnitCircleModel(degrees),[degrees]);
  const position={first:"Πρώτο τεταρτημόριο",second:"Δεύτερο τεταρτημόριο","x-axis":"Πάνω στον οριζόντιο άξονα","y-axis":"Πάνω στον κατακόρυφο άξονα"}[model.location];
  const expression=key=>model.exact?model.exact[key]:latexDecimal(key==="cos"?model.cosine:key==="sin"?model.sine:model.tangent);
  return <section aria-labelledby={headingId} className="overflow-hidden rounded-2xl border border-indigo-200 bg-gradient-to-br from-indigo-50 via-white to-teal-50 dark:border-indigo-500/30 dark:from-indigo-500/10 dark:via-card dark:to-teal-500/10">
    <div className="flex items-start gap-3 border-b border-indigo-200/80 p-4 sm:p-5 dark:border-indigo-500/25"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[#1f4e7b] text-white"><Sparkles className="h-5 w-5"/></span><div><div className="text-xs font-extrabold uppercase tracking-widest text-indigo-800 dark:text-indigo-300">Δυναμικό εργαστήριο</div><h3 id={headingId} className="mt-1 text-xl font-black">Μία γωνία, δύο συντεταγμένες</h3><p className="mt-2 text-base leading-relaxed text-muted-foreground">Κίνησε το Μ στο επάνω ημικύκλιο. Η οριζόντια συντεταγμένη είναι το συνημίτονο και η κατακόρυφη το ημίτονο. Παρατήρησε τι αλλάζει στις 90°.</p></div></div>
    <div className="space-y-5 p-4 sm:p-5"><div className="flex flex-wrap gap-2">{UNIT_CIRCLE_ANGLES.map(a=><button key={a} type="button" aria-pressed={degrees===a} onClick={()=>setDegrees(a)} className={`rounded-xl border px-3 py-2.5 text-base font-bold ${degrees===a?"border-indigo-700 bg-indigo-700 text-white":"border-border bg-background"}`}>{a}°</button>)}</div>
      <div className="space-y-4 rounded-xl border border-border bg-background p-4"><label className="block text-base font-bold">Γωνία ω={degrees}°<input type="range" min="0" max="180" step="1" value={degrees} aria-label="Γωνία ω" aria-valuetext={`${degrees} μοίρες`} onChange={e=>setDegrees(Number(e.target.value))} className="mt-3 block w-full accent-indigo-700"/></label><div className="flex flex-wrap gap-2"><button type="button" aria-pressed={projections} onClick={()=>setProjections(!projections)} className="rounded-xl border border-border bg-background px-3 py-2.5 text-base font-bold">{projections?"Κρύψε τις προβολές":"Δείξε τις προβολές"}</button><button type="button" onClick={()=>{setDegrees(120);setProjections(true);}} className="inline-flex items-center gap-2 rounded-xl border border-border bg-background px-3 py-2.5 text-base font-bold"><RotateCcw className="h-4 w-4"/>Αρχική θέση</button></div></div>
      <div className="flex flex-wrap gap-4 text-base font-bold"><span className="text-[#1f4e7b] dark:text-sky-300">x = συνω</span><span className="text-teal-800 dark:text-teal-300">y = ημω</span><span className="text-amber-800 dark:text-amber-300">ΟΜ = 1</span></div>
      <CircleDrawing model={model} changeAngle={setDegrees} projections={projections}/>
      <p className="flex items-start gap-2 text-base leading-relaxed text-muted-foreground"><Move className="mt-1 h-4 w-4 shrink-0"/> Σύρε το Μ ή εστίασέ το με Tab. Τα βέλη μεταβάλλουν τη γωνία κατά 1°, ενώ Home και End επιλέγουν 0° και 180°.</p>
      <div role="status" className="rounded-xl border border-indigo-300 bg-indigo-50 p-4 text-base leading-relaxed dark:border-indigo-500/30 dark:bg-indigo-500/10"><h4 className="text-lg font-black">{position} · ω={degrees}°</h4><p className="mt-2">Ημίτονο: {sign(model.signs.sine)} · Συνημίτονο: {sign(model.signs.cosine)} · Εφαπτομένη: {sign(model.signs.tangent)}.</p><p className="mt-2">{degrees===90?"Το Μ είναι στο (0,1). Επειδή συν90°=0, η εφαπτομένη δεν ορίζεται: δεν διαιρούμε με μηδέν.":model.location==="second"?"Το Μ βρίσκεται αριστερά από τον κατακόρυφο άξονα και πάνω από τον οριζόντιο: x<0 και y>0. Το συνημίτονο είναι αρνητικό, παρότι η απόσταση από τον άξονα είναι θετική.":model.location==="first"?"Και οι δύο συντεταγμένες είναι θετικές. Ο ορισμός συμφωνεί με τους γνωστούς λόγους πλευρών ορθογωνίου τριγώνου, με υποτείνουσα ΟΜ=1.":"Το Μ βρίσκεται πάνω στον οριζόντιο άξονα, άρα η τεταγμένη του και το ημίτονο είναι 0. Η εφαπτομένη είναι επίσης 0, αφού το συνημίτονο δεν είναι μηδέν."}</p></div>
      <div className="grid gap-3 sm:grid-cols-3">{[["Συνημίτονο · τετμημένη","cos","\\cos",model.cosine],["Ημίτονο · τεταγμένη","sin","\\sin",model.sine],["Εφαπτομένη · y/x","tan","\\tan",model.tangent]].map(([label,key,command,value])=><div key={key} className="rounded-xl border border-border bg-background p-4 text-center"><div className="mb-2 text-base font-bold text-muted-foreground">{label}</div>{value===null?<p className="text-lg font-extrabold">Δεν ορίζεται</p>:<MathText className="text-xl font-extrabold" text={`$${command} ${degrees}^\\circ ${model.exact?"=":"\\approx"} ${expression(key)}$`}/>}</div>)}</div>
      <div className="rounded-xl border border-border bg-background p-4 text-base leading-relaxed"><MathText className="block font-bold" text={`$M=(\\cos\\omega,\\sin\\omega) ${model.exact?"=":"\\approx"} \\left(${expression("cos")};\\;${expression("sin")}\\right)$`}/><p className="mt-3 text-muted-foreground">Οι τύποι γράφουν cos για το συν, sin για το ημ και tan για την εφ. Οι δεκαδικές τιμές με ≈ έχουν στρογγυλοποιηθεί σε τέσσερα δεκαδικά. Η θέση και το πρόσημο υπολογίζονται πριν από τη στρογγυλοποίηση.</p><MathText className="mt-3 block" text={"$\\cos^2\\omega+\\sin^2\\omega=1,\\qquad \\tan\\omega=\\frac{\\sin\\omega}{\\cos\\omega}\\quad(\\cos\\omega\\ne0)$."}/></div>
      <div className="overflow-x-auto rounded-xl border border-border bg-background"><table className="w-full min-w-[440px] text-left text-base"><caption className="p-4 text-left text-lg font-black">Τιμές πάνω στους άξονες</caption><thead className="border-b border-border bg-secondary/50"><tr><th className="px-4 py-3">ω</th><th className="px-4 py-3">Μ</th><th className="px-4 py-3">ημω</th><th className="px-4 py-3">συνω</th><th className="px-4 py-3">εφω</th></tr></thead><tbody>{[[0,"(1,0)",0,1,"0"],[90,"(0,1)",1,0,"Δεν ορίζεται"],[180,"(−1,0)",0,-1,"0"]].map(([a,p,s,c,t])=><tr key={a} className="border-b border-border last:border-0"><th className="px-4 py-3">{a}°</th><td className="px-4 py-3">{p}</td><td className="px-4 py-3">{s}</td><td className="px-4 py-3">{c}</td><td className="px-4 py-3">{t}</td></tr>)}</tbody></table></div>
    </div>
  </section>;
}
