import { useId, useMemo, useState } from "react";
import { FlipHorizontal2, RotateCcw, Sparkles } from "lucide-react";
import { MathText } from "@/components/MathText";
import { centroid } from "./congruenceModel";
import { buildSimilarityModel, SIMILARITY_MODES, SIMILARITY_EDGES, similarityNames } from "./similarityModel";
const format = (x) => x.toLocaleString("el-GR", { maximumFractionDigits: 2 });
const measured = (x) => `${Math.abs(x-Math.round(x*100)/100)>1e-8?"≈ ":""}${format(x)}`;
const FIRST=["Α","Β","Γ"];
function Diagram({model,names}){
  const titleId=useId();
  const radius=Math.max(...[model.first,model.second].flatMap(points=>{const c=centroid(points);return points.map(p=>Math.hypot(p.x-c.x,p.y-c.y));}));
  const scale=118/radius;
  const project=(points,x)=>{const c=centroid(points);return points.map(p=>({x:x+(p.x-c.x)*scale,y:200-(p.y-c.y)*scale}));};
  const sets=[project(model.first,180),project(model.second,540)];
  const colours=["var(--sim-ab)","var(--sim-ac)","var(--sim-bc)"];
  return <div className="overflow-x-auto rounded-xl border border-teal-200 bg-white p-2 [--sim-ab:#1f4e7b] [--sim-ac:#0f766e] [--sim-bc:#b45309] dark:border-teal-500/30 dark:bg-slate-950 dark:[--sim-ab:#7dd3fc] dark:[--sim-ac:#5eead4] dark:[--sim-bc:#fbbf24]">
    <svg viewBox="0 0 720 365" className="min-w-[550px] w-full" role="img" aria-labelledby={titleId}><title id={titleId}>Τρίγωνα ΑΒΓ και {names.join("")} σε κοινή κλίμακα. {model.similar?"Όμοια τρίγωνα με λόγο "+format(model.ratio):"Αντιπαράδειγμα: δύο ανάλογες πλευρές και μία ίση μη περιεχόμενη γωνία δεν αρκούν."}</title>
      {sets.map((points,j)=><g key={j}><rect x={j*360+8} y="44" width="344" height="300" rx="14" fill="currentColor" fillOpacity=".025"/><text x={j*360+24} y="29" fill="currentColor" fontWeight="800" fontSize="18">{j?`Τρίγωνο ${names.join("")}`:"Τρίγωνο ΑΒΓ"}</text><polygon points={points.map(p=>`${p.x},${p.y}`).join(" ")} fill="var(--sim-ac)" fillOpacity=".06"/>
        {SIMILARITY_EDGES.map(([a,b],i)=><line key={i} x1={points[a].x} y1={points[a].y} x2={points[b].x} y2={points[b].y} stroke={colours[i]} strokeWidth="4" strokeDasharray={j?"9 4":undefined}/>)}
        {points.map((p,i)=>{const c=centroid(points),dx=p.x-c.x,dy=p.y-c.y,d=Math.hypot(dx,dy);return <g key={i}><circle cx={p.x} cy={p.y} r="4" fill="currentColor"/><text x={p.x+dx/d*24} y={p.y+dy/d*24+6} textAnchor="middle" fontSize="19" fontWeight="800" fill="currentColor">{(j?names:FIRST)[i]}</text></g>;})}
      </g>)}<text x="360" y="361" textAnchor="middle" fill="currentColor" fontSize="14">Ίδια χρώματα: αντίστοιχες πλευρές. Δεν δηλώνουν απαραίτητα ίσα μήκη.</text>
    </svg>
  </div>;
}
export function SimilarityExplorer(){
  const headingId=useId();const [modeId,setModeId]=useState("aa"),[quarters,setQuarters]=useState(6),[parameter,setParameter]=useState(50),[rotation,setRotation]=useState(25),[reflected,setReflected]=useState(false),[renamed,setRenamed]=useState(false);
  const mode=SIMILARITY_MODES.find(m=>m.id===modeId),names=similarityNames(renamed);
  const model=useMemo(()=>buildSimilarityModel(modeId,quarters,parameter,rotation,reflected),[modeId,quarters,parameter,rotation,reflected]);
  const selectMode=(id)=>{setModeId(id);setParameter(SIMILARITY_MODES.find(m=>m.id===id).initial);};
  const reset=()=>{selectMode("aa");setQuarters(6);setRotation(25);setReflected(false);setRenamed(false);};
  const ratioText=SIMILARITY_EDGES.map(([a,b])=>`${names[a]}${names[b]}/${FIRST[a]}${FIRST[b]}`);
  const status=model.similar?`ΑΒΓ ∼ ${names.join("")} · κ=${format(model.ratio)}`:"Τα δεδομένα ΠΠΓ δεν αρκούν";
  return <section aria-labelledby={headingId} className="overflow-hidden rounded-2xl border border-teal-200 bg-gradient-to-br from-teal-50 via-white to-sky-50 dark:border-teal-500/30 dark:from-teal-500/10 dark:via-card dark:to-sky-500/10">
    <div className="flex items-start gap-3 border-b border-teal-200/80 p-4 sm:p-5 dark:border-teal-500/25"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[#1f4e7b] text-white"><Sparkles className="h-5 w-5"/></span><div><div className="text-xs font-extrabold uppercase tracking-widest text-teal-800 dark:text-teal-300">Δυναμικό εργαστήριο</div><h3 id={headingId} className="mt-1 text-xl font-black">Άλλαξε τη θέση, κράτησε την αντιστοιχία</h3><p className="mt-2 text-base leading-relaxed text-muted-foreground">Δοκίμασε τα τρία κριτήρια και ένα αντιπαράδειγμα. Περίστρεψε το δεύτερο τρίγωνο ή άλλαξε τα ονόματά του· η αντιστοιχία ακολουθεί τις κορυφές.</p></div></div>
    <div className="space-y-5 p-4 sm:p-5"><div className="flex flex-wrap gap-2">{SIMILARITY_MODES.map(m=><button key={m.id} type="button" aria-pressed={modeId===m.id} onClick={()=>selectMode(m.id)} className={`rounded-xl border px-4 py-2.5 text-base font-bold ${modeId===m.id?"border-teal-700 bg-teal-700 text-white":"border-border bg-background"}`}>{m.label}</button>)}<button type="button" onClick={reset} className="inline-flex items-center gap-2 rounded-xl border border-border bg-background px-3 py-2.5 text-base font-bold"><RotateCcw className="h-4 w-4"/>Αρχική θέση</button></div>
      <div className="grid gap-4 rounded-xl border border-border bg-background p-4 sm:grid-cols-2"><label className="text-base font-bold">{modeId==="ssa"?"Δύο δοσμένοι λόγοι πλευρών":"Λόγος από ΑΒΓ προς "+names.join("")}: κ={format(model.ratio)}<input type="range" min="1" max="12" step="1" value={quarters} aria-label="Θετικός λόγος κ" aria-valuetext={`κ=${format(model.ratio)}`} onChange={e=>setQuarters(Number(e.target.value))} className="mt-3 block w-full accent-teal-700"/><span className="mt-2 block text-sm font-normal text-muted-foreground">Από 0,25 έως 3. Εδώ κ είναι λόγος θετικών μηκών.</span></label>
      {mode.min!==undefined&&<label className="text-base font-bold">{mode.parameter}: {format(parameter)}{mode.unit}<input type="range" min={mode.min} max={mode.max} step={mode.step} value={parameter} aria-label={mode.parameter} onChange={e=>setParameter(Number(e.target.value))} className="mt-3 block w-full accent-sky-700"/></label>}
      <label className="text-base font-bold">Περιστροφή δεύτερου τριγώνου: {rotation}°<input type="range" min="0" max="360" step="5" value={rotation} aria-label="Περιστροφή δεύτερου τριγώνου" onChange={e=>setRotation(Number(e.target.value))} className="mt-3 block w-full accent-sky-700"/></label>
      <div className="flex flex-wrap items-center gap-2"><button type="button" aria-pressed={reflected} onClick={()=>setReflected(!reflected)} className="inline-flex items-center gap-2 rounded-xl border border-border bg-background px-3 py-2.5 text-base font-bold"><FlipHorizontal2 className="h-4 w-4"/>Κατοπτρισμός</button><button type="button" aria-pressed={renamed} onClick={()=>setRenamed(!renamed)} className="rounded-xl border border-border bg-background px-3 py-2.5 text-base font-bold">Άλλαξε τα ονόματα</button></div></div>
      <Diagram model={model} names={names}/>
      <div role="status" className={`rounded-xl border p-4 ${model.similar?"border-teal-300 bg-teal-50 dark:border-teal-500/30 dark:bg-teal-500/10":"border-amber-300 bg-amber-50 dark:border-amber-500/30 dark:bg-amber-500/10"}`}><h4 className="text-lg font-black">{status}</h4><p className="mt-2 text-base leading-relaxed">{model.explanation}</p></div>
      <div className="rounded-xl border border-border bg-background p-4 text-base leading-relaxed"><p className="font-bold">Αντιστοιχία: {FIRST.map((n,i)=>`${n} ↔ ${names[i]}`).join(" · ")}</p><p className="mt-2">{model.similar?`${ratioText.join(" = ")} = ${format(model.ratio)}.`:`Δίνονται ${ratioText[0]} = ${ratioText[1]} = ${format(model.ratio)} και γωνία Β = γωνία ${names[1]} = 30°. Σύγκρινε τον τρίτο λόγο.`}</p><p className="mt-2 text-muted-foreground">{modeId==="aa"?`Δεδομένες γωνίες: Α=${parameter}° και Β=40°, ίσες με τις αντίστοιχες. Η τρίτη είναι ${140-parameter}°.`:modeId==="sas"?`Η γωνία Α=${parameter}° βρίσκεται ανάμεσα στις ΑΒ και ΑΓ. Αντίστοιχη είναι η γωνία ${names[0]}.`:modeId==="sss"?"Δίνονται και οι τρεις λόγοι αντίστοιχων πλευρών.":"Οι δύο γνωστές πλευρές συναντώνται στην Α, αλλά η γνωστή γωνία βρίσκεται στη Β."}</p></div>
      <div className="overflow-x-auto rounded-xl border border-border bg-background"><table className="w-full min-w-[540px] text-left text-base"><caption className="p-4 text-left text-lg font-black">Αντίστοιχες πλευρές — κοινή μονάδα μήκους</caption><thead className="border-b border-border bg-secondary/50"><tr><th className="px-3 py-3">Αντιστοιχία</th><th className="px-3 py-3">Πρώτο</th><th className="px-3 py-3">Δεύτερο</th><th className="px-3 py-3">Δεύτερο / πρώτο</th></tr></thead><tbody>{SIMILARITY_EDGES.map(([a,b],i)=><tr key={i} className="border-b border-border"><th className="px-3 py-3">{FIRST[a]}{FIRST[b]} ↔ {names[a]}{names[b]}{model.givenSideIndices.includes(i)?" · δεδομένα":""}</th><td className="px-3 py-3">{measured(model.firstMeasures.sides[i])}</td><td className="px-3 py-3">{measured(model.secondMeasures.sides[i])}</td><td className="px-3 py-3 font-extrabold">{measured(model.ratios[i])}</td></tr>)}<tr><th className="px-3 py-3">Περίμετρος</th><td className="px-3 py-3">{measured(model.firstPerimeter)}</td><td className="px-3 py-3">{measured(model.secondPerimeter)}</td><td className="px-3 py-3 font-extrabold">{measured(model.secondPerimeter/model.firstPerimeter)}</td></tr></tbody></table></div>
      <div className="grid gap-2 sm:grid-cols-3">{FIRST.map((n,i)=><div key={n} className="rounded-xl border border-border bg-background p-3 text-base"><span className="font-bold">{n} ↔ {names[i]}{model.givenAngleIndices.includes(i)?" · δεδομένα":""}</span><p className="mt-2">{measured(model.firstMeasures.angles[i])}° / {measured(model.secondMeasures.angles[i])}°</p></div>)}</div>
      <MathText className="block text-base leading-relaxed text-muted-foreground" text="Οι ενδείξεις με $\\approx$ είναι στρογγυλοποιημένες. Η ομοιότητα ελέγχεται από την ακριβή κατασκευή και τα κριτήρια, όχι από τις μετρήσεις της οθόνης. Η περιστροφή και ο κατοπτρισμός διατηρούν μήκη και γωνίες."/>
    </div>
  </section>;
}
