import {useId,useMemo,useState} from "react";
import {ArrowLeftRight,Move,RotateCcw,Sparkles} from "lucide-react";
import {MathText} from "@/components/MathText";
import {unitCircleAngleFromPoint} from "./unitCircleModel";
import {buildSupplementaryModel} from "./supplementaryModel";
const decimal=x=>x.toLocaleString("el-GR",{maximumFractionDigits:4});
const value=(m,key)=>m.exact?m.exact[key]:decimal(key==="sin"?m.sine:key==="cos"?m.cosine:m.tangent).replace(",","{,}");
const PRESETS=[0,30,45,60,90];
function ReflectionDrawing({model,onAngle,projections}){
  const titleId=useId(),cx=340,cy=250,r=175,a=model.first,b=model.second;
  const M={x:cx+r*a.x,y:cy-r*a.y},N={x:cx+r*b.x,y:cy-r*b.y};
  const move=e=>{const svg=e.currentTarget.ownerSVGElement,matrix=svg?.getScreenCTM();if(!matrix)return;const p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const q=p.matrixTransform(matrix.inverse());const angle=unitCircleAngleFromPoint({x:(q.x-cx)/r,y:(cy-q.y)/r});if(angle!==null)onAngle(angle);};
  const release=e=>{if(e.currentTarget.hasPointerCapture(e.pointerId))e.currentTarget.releasePointerCapture(e.pointerId);};
  const keyMove=e=>{const d={ArrowRight:1,ArrowUp:1,ArrowLeft:-1,ArrowDown:-1}[e.key];if(d){e.preventDefault();onAngle(Math.max(0,Math.min(180,a.degrees+d)));}else if(e.key==="Home"||e.key==="End"){e.preventDefault();onAngle(e.key==="Home"?0:180);}};
  const pointLabel=(p,name,x,colour)=><text x={p.x+(x>=0?17:-17)} y={p.y+(a.y>0.85?24:-13)} textAnchor={x>=0?"start":"end"} fill={colour} fontSize="20" fontWeight="800">{name}</text>;
  return <div className="overflow-x-auto rounded-xl border border-violet-200 bg-white p-2 [--supp-m:#b45309] [--supp-n:#7c3aed] [--supp-y:#0f766e] dark:border-violet-500/30 dark:bg-slate-950 dark:[--supp-m:#fbbf24] dark:[--supp-n:#c4b5fd] dark:[--supp-y:#5eead4]">
    <svg viewBox="0 0 680 465" className="min-w-[500px] w-full" role="group" aria-labelledby={titleId}><title id={titleId}>Συμμετρικά σημεία Μ και Ν στον μοναδιαίο κύκλο για γωνίες {a.degrees}° και {b.degrees}°. Έχουν ίδια τεταγμένη και αντίθετες τετμημένες.</title>
      <circle cx={cx} cy={cy} r={r} fill="none" stroke="currentColor" strokeWidth="1.5" opacity=".16" strokeDasharray="6 5"/><path d={`M ${cx+r} ${cy} A ${r} ${r} 0 0 0 ${cx-r} ${cy}`} fill="none" stroke="currentColor" strokeWidth="2.5" opacity=".65"/>
      <g stroke="currentColor" strokeWidth="1.7" opacity=".65"><line x1="100" y1={cy} x2="580" y2={cy}/><path d="M580 250l-10 -5v10z" fill="currentColor"/><line x1={cx} y1="440" x2={cx} y2="35"/><path d="M340 35l-5 10h10z" fill="currentColor"/></g>
      <g fill="currentColor" fontSize="17"><text x="589" y="256">x</text><text x="351" y="40">y</text><text x={cx+12} y={cy+22}>Ο</text><text x={cx-r} y={cy+23} textAnchor="middle">−1</text><text x={cx+r} y={cy+23} textAnchor="middle">1</text><text x={cx+12} y={cy-r+5}>1</text><text x={cx-r} y={cy+47} textAnchor="middle">180°</text><text x={cx+r} y={cy+47} textAnchor="middle">0°</text><text x="314" y="56">90°</text></g>
      {projections&&<><line x1={M.x} y1={M.y} x2={N.x} y2={N.y} stroke="var(--supp-y)" strokeWidth="2.5" strokeDasharray="6 4"/><line x1={cx} y1={cy} x2={cx} y2={M.y} stroke="var(--supp-y)" strokeWidth="5"/>{[[M,"var(--supp-m)"],[N,"var(--supp-n)"]].map(([p,colour],i)=><g key={i}><line x1={p.x} y1={p.y} x2={p.x} y2={cy} stroke={colour} strokeWidth="2" strokeDasharray="5 4"/><line x1={cx} y1={cy} x2={p.x} y2={cy} stroke={colour} strokeWidth="4"/></g>)}</>}
      {[[a,"var(--supp-m)",40],[b,"var(--supp-n)",58]].map(([m,colour,rad],i)=><g key={i}><line x1={cx} y1={cy} x2={cx+r*m.x} y2={cy-r*m.y} stroke={colour} strokeWidth="2.8"/>{m.degrees>0&&<path d={`M ${cx+rad} ${cy} A ${rad} ${rad} 0 0 0 ${cx+rad*m.x} ${cy-rad*m.y}`} fill="none" stroke={colour} strokeWidth="2"/>}</g>)}
      {!model.coincident&&<><circle cx={N.x} cy={N.y} r="6" fill="var(--supp-n)"/>{pointLabel(N,"Ν",b.x,"var(--supp-n)")}</>}
      <g role="button" aria-label="Μετακίνηση του Μ με τα βέλη" tabIndex="0" onKeyDown={keyMove} onPointerDown={e=>{e.preventDefault();e.currentTarget.focus();e.currentTarget.setPointerCapture(e.pointerId);move(e);}} onPointerMove={e=>{if(e.currentTarget.hasPointerCapture(e.pointerId))move(e);}} onPointerUp={release} onPointerCancel={release} className="group cursor-grab touch-none outline-none"><circle cx={M.x} cy={M.y} r="23" fill="transparent"/><circle cx={M.x} cy={M.y} r="7" fill="var(--supp-m)" strokeWidth="3" className="stroke-white group-focus:stroke-violet-500 dark:stroke-slate-100"/>{model.coincident?<text x={M.x+20} y={M.y-14} fill="var(--supp-m)" fontSize="19" fontWeight="800">Μ ≡ Ν</text>:pointLabel(M,"Μ",a.x,"var(--supp-m)")}</g>
      <text x="340" y="455" textAnchor="middle" fill="currentColor" fontSize="16">ΟΜ = ΟΝ = 1 · {a.degrees}° + {b.degrees}° = 180°</text>
    </svg>
  </div>;
}
export function SupplementaryExplorer(){
  const headingId=useId();const [degrees,setDegrees]=useState(60),[projections,setProjections]=useState(true);
  const model=useMemo(()=>buildSupplementaryModel(degrees),[degrees]),a=model.first,b=model.second;
  const coordinate=m=>`$\\left(${value(m,"cos")};\\;${value(m,"sin")}\\right)$`;
  return <section aria-labelledby={headingId} className="overflow-hidden rounded-2xl border border-violet-200 bg-gradient-to-br from-violet-50 via-white to-teal-50 dark:border-violet-500/30 dark:from-violet-500/10 dark:via-card dark:to-teal-500/10">
    <div className="flex items-start gap-3 border-b border-violet-200/80 p-4 sm:p-5 dark:border-violet-500/25"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[#1f4e7b] text-white"><Sparkles className="h-5 w-5"/></span><div><div className="text-xs font-extrabold uppercase tracking-widest text-violet-800 dark:text-violet-300">Δυναμικό εργαστήριο</div><h3 id={headingId} className="mt-1 text-xl font-black">Μία συμμετρία, τρεις σχέσεις</h3><p className="mt-2 text-base leading-relaxed text-muted-foreground">Το Ν είναι το συμμετρικό του Μ ως προς τον κατακόρυφο άξονα. Κίνησε το Μ και σύγκρινε τις συντεταγμένες τους.</p></div></div>
    <div className="space-y-5 p-4 sm:p-5"><div className="flex flex-wrap gap-2">{PRESETS.map(angle=>{const active=degrees===angle||degrees===180-angle;return <button type="button" key={angle} aria-pressed={active} onClick={()=>setDegrees(angle)} className={`rounded-xl border px-3 py-2.5 text-base font-bold ${active?"border-violet-700 bg-violet-700 text-white":"border-border bg-background"}`}>{angle}° + {180-angle}°</button>;})}</div>
      <div className="space-y-4 rounded-xl border border-border bg-background p-4"><label className="block text-base font-bold">Πρώτη γωνία ω={degrees}° · δεύτερη 180°−ω={b.degrees}°<input type="range" min="0" max="180" step="1" value={degrees} aria-label="Πρώτη γωνία ω" aria-valuetext={`${degrees} μοίρες· παραπληρωματική ${b.degrees} μοίρες`} onChange={e=>setDegrees(Number(e.target.value))} className="mt-3 block w-full accent-violet-700"/></label><div className="flex flex-wrap gap-2"><button type="button" onClick={()=>setDegrees(180-degrees)} className="inline-flex items-center gap-2 rounded-xl border border-border bg-background px-3 py-2.5 text-base font-bold"><ArrowLeftRight className="h-4 w-4"/>Αντάλλαξε τις γωνίες</button><button type="button" aria-pressed={projections} onClick={()=>setProjections(!projections)} className="rounded-xl border border-border bg-background px-3 py-2.5 text-base font-bold">{projections?"Κρύψε τις προβολές":"Δείξε τις προβολές"}</button><button type="button" onClick={()=>{setDegrees(60);setProjections(true);}} className="inline-flex items-center gap-2 rounded-xl border border-border bg-background px-3 py-2.5 text-base font-bold"><RotateCcw className="h-4 w-4"/>Αρχική θέση</button></div></div>
      <div className="flex flex-wrap gap-4 text-base font-bold"><span className="text-amber-800 dark:text-amber-300">Μ: ω={degrees}°</span><span className="text-violet-800 dark:text-violet-300">Ν: 180°−ω={b.degrees}°</span><span className="text-teal-800 dark:text-teal-300">Ίδια τεταγμένη</span></div>
      <ReflectionDrawing model={model} onAngle={setDegrees} projections={projections}/>
      <p className="flex items-start gap-2 text-base leading-relaxed text-muted-foreground"><Move className="mt-1 h-4 w-4 shrink-0"/> Σύρε το Μ ή εστίασέ το με Tab και χρησιμοποίησε τα βέλη. Το Ν ακολουθεί συμμετρικά. Home και End επιλέγουν τα δύο άκρα του ημικυκλίου.</p>
      <div role="status" className="rounded-xl border border-violet-300 bg-violet-50 p-4 text-base leading-relaxed dark:border-violet-500/30 dark:bg-violet-500/10"><h4 className="text-lg font-black">{model.coincident?"90° και 90° — τα σημεία συμπίπτουν":`${degrees}° και ${b.degrees}° — άθροισμα 180°`}</h4><p className="mt-2">{model.coincident?"Τα Μ και Ν είναι το ίδιο σημείο (0,1). Τα ημίτονα είναι 1 και τα συνημίτονα 0. Οι δύο εφαπτομένες δεν ορίζονται.":degrees===0||degrees===180?"Τα σημεία είναι στα δύο άκρα του οριζόντιου άξονα. Έχουν ημίτονο 0, συνημίτονα 1 και −1 και εφαπτομένες 0.":"Η συμμετρία διατηρεί την τεταγμένη y και αντιστρέφει την τετμημένη x. Άρα τα ημίτονα είναι ίδια, τα συνημίτονα αντίθετα και οι εφαπτομένες αντίθετες."}</p></div>
      <div className="grid gap-3 sm:grid-cols-2">{[["Μ",a],["Ν",b]].map(([name,m])=><div key={name} className="rounded-xl border border-border bg-background p-4"><p className="mb-2 text-base font-bold">{name} · {m.degrees}° {m.exact?"· ακριβείς τιμές":"· προσέγγιση"}</p><MathText className="text-lg font-bold" text={`$${name}${m.exact?"=":"\\approx"}${coordinate(m).slice(1,-1)}$`}/></div>)}</div>
      <div className="overflow-x-auto rounded-xl border border-border bg-background"><table className="w-full min-w-[570px] text-left text-base"><caption className="p-4 text-left text-lg font-black">Σύγκρινε τις δύο γωνίες</caption><thead className="border-b border-border bg-secondary/50"><tr><th className="px-4 py-3">Αριθμός</th><th className="px-4 py-3">ω={degrees}°</th><th className="px-4 py-3">180°−ω={b.degrees}°</th><th className="px-4 py-3">Σχέση</th></tr></thead><tbody>{[["Ημίτονο","sin","ίδιες τιμές"],["Συνημίτονο","cos","αντίθετες τιμές"],["Εφαπτομένη","tan",model.tangentDefined?"αντίθετες τιμές":"δεν ορίζονται"]].map(([label,key,relation])=><tr key={key} className="border-b border-border last:border-0"><th className="px-4 py-3">{label}</th>{[a,b].map((m,i)=><td key={i} className="px-4 py-3">{key==="tan"&&m.tangent===null?"Δεν ορίζεται":<MathText text={`$${m.exact?"":"\\approx "}${value(m,key)}$`}/>}</td>)}<td className="px-4 py-3 font-bold">{relation}</td></tr>)}</tbody></table></div>
      <div className="space-y-3 rounded-xl border border-teal-200 bg-background p-4 text-lg dark:border-teal-500/30"><MathText className="block" text={"$\\sin(180^\\circ-\\omega)=\\sin\\omega$"}/><MathText className="block" text={"$\\cos(180^\\circ-\\omega)=-\\cos\\omega$"}/><MathText className="block" text={"$\\tan(180^\\circ-\\omega)=-\\tan\\omega\\quad(\\omega\\ne90^\\circ)$"}/><p className="text-base leading-relaxed text-muted-foreground">Οι σχέσεις αναφέρονται στο διάστημα 0°–180°. Η σχέση της εφαπτομένης εφαρμόζεται μόνο όταν ορίζονται και οι δύο τιμές. Οι δεκαδικές ενδείξεις με ≈ είναι στρογγυλοποιημένες σε τέσσερα δεκαδικά.</p></div>
    </div>
  </section>;
}
