import {useId,useMemo,useState} from "react";
import {RotateCcw,Sparkles} from "lucide-react";
import {MathText} from "@/components/MathText";
import {buildTrigIdentityModel} from "./trigIdentityModel";
const presets={sin:[[3,5],[5,13],[1,2],[1,1],[0,1]],cos:[[-3,5],[-12,13],[1,2],[0,1],[-1,1],[1,1]]};
const command={sin:"\\sin",cos:"\\cos"},name={sin:"ημω",cos:"συνω"};
const decimal=n=>n.toLocaleString("el-GR",{maximumFractionDigits:4});
const pointName=p=>p.location==="acute"?"Οξεία γωνία":p.location==="obtuse"?"Αμβλεία γωνία":p.location==="right"?"ω=90°":p.x>0?"ω=0°":"ω=180°";
function IdentityDrawing({model}){
  const titleId=useId(),cx=300,cy=230,r=165;
  return <div className="overflow-x-auto rounded-xl border border-sky-200 bg-white p-2 [--ti-x:#1f4e7b] [--ti-y:#0f766e] [--ti-m:#b45309] [--ti-n:#7c3aed] dark:border-sky-500/30 dark:bg-slate-950 dark:[--ti-x:#7dd3fc] dark:[--ti-y:#5eead4] dark:[--ti-m:#fbbf24] dark:[--ti-n:#c4b5fd]">
    <svg viewBox="0 0 620 335" className="min-w-[420px] w-full" role="img" aria-labelledby={titleId}><title id={titleId}>Σημεία του επάνω μοναδιαίου ημικυκλίου με {name[model.kind]}={decimal(model.known)}. Επιτρεπτές θέσεις με τα δεδομένα: {model.solutions.length}.</title>
      <path d={`M${cx+r} ${cy}A${r} ${r} 0 0 0 ${cx-r} ${cy}`} fill="none" stroke="currentColor" strokeWidth="2.5" opacity=".65"/>
      <g stroke="currentColor" strokeWidth="1.5" opacity=".65"><path d="M70 230H505m-10-5 10 5-10 5M300 285V30m-5 10 5-10 5 10" fill="none"/></g>
      <g fill="currentColor" fontSize="17"><text x="515" y="236">x = συνω</text><text x="313" y="34">y = ημω</text><text x="310" y="254">Ο</text><text x={cx-r} y="254" textAnchor="middle">−1</text><text x={cx+r} y="254" textAnchor="middle">1</text><text x="313" y="68">1</text></g>
      {model.kind==="sin"?<line x1="85" y1={cy-r*model.known} x2="520" y2={cy-r*model.known} stroke="var(--ti-y)" strokeWidth="2" strokeDasharray="6 4"/>:<line x1={cx+r*model.known} y1="45" x2={cx+r*model.known} y2="275" stroke="var(--ti-x)" strokeWidth="2" strokeDasharray="6 4"/>}
      {model.candidates.map(p=>{const px=cx+r*p.x,py=cy-r*p.y,active=model.solutions.includes(p),colour=p.index===0?"var(--ti-m)":"var(--ti-n)",right=p.x>=0;return <g key={p.index} opacity={active?1:.22}><title>{pointName(p)} · συνω={decimal(p.x)}, ημω={decimal(p.y)}</title><path d={`M${cx} ${cy}H${px}V${py}Z`} fill={colour} fillOpacity=".07" stroke={colour} strokeWidth="2"/><line x1={cx} y1={cy} x2={px} y2={py} stroke={colour} strokeWidth="2.5"/><circle cx={px} cy={py} r="6.5" fill={colour}/><text x={px+(right?14:-14)} y={py-13} textAnchor={right?"start":"end"} fontSize="20" fontWeight="800" fill={colour}>{model.candidates.length===1?"Μ":`Μ${p.index===0?"₁":"₂"}`}</text></g>;})}
      <text x="300" y="315" fill="currentColor" fontSize="17" textAnchor="middle">Κάθε ακτίνα έχει μήκος 1 · x² + y² = 1</text>
    </svg>
  </div>;
}
export function TrigIdentityExplorer(){
  const headingId=useId();const [kind,setKind]=useState("sin"),[n,setN]=useState(3),[d,setD]=useState(5),[region,setRegion]=useState("all");
  const model=useMemo(()=>buildTrigIdentityModel(kind,n,d,region),[kind,n,d,region]),other=kind==="sin"?"cos":"sin";
  const reset=()=>{setKind("sin");setN(3);setD(5);setRegion("all");};
  const mode=k=>{setKind(k);setN(k==="sin"?3:-3);setD(5);setRegion("all");};
  const status=model.solutions.length===0?"Τα δεδομένα δεν δίνουν τέτοια γωνία":model.solutions.length===2?"Δύο δυνατές θέσεις — χρειάζεται πληροφορία για το πρόσημο":"Μία δυνατή θέση";
  const reason=model.solutions.length===0?"Οι 0°, 90° και 180° δεν είναι οξείες ή αμβλείες. Η επιλεγμένη τιμή δεν συνδυάζεται με το συγκεκριμένο είδος γωνίας.":kind==="cos"?"Το ημίτονο είναι μη αρνητικό σε όλο το 0°–180°, οπότε επιλέγουμε τη μη αρνητική ρίζα.":model.known===1?"Η τιμή ημω=1 αντιστοιχεί μόνο στις 90°. Το συνημίτονο είναι 0 και η εφαπτομένη δεν ορίζεται.":model.known===0?"Η τιμή ημω=0 εμφανίζεται στις 0° και 180°. Τα συνημίτονα είναι 1 και −1 και οι εφαπτομένες 0.":region==="all"?"Το ίδιο θετικό ημίτονο μπορεί να αντιστοιχεί σε οξεία ή αμβλεία γωνία. Χωρίς άλλο δεδομένο κρατάμε και τις δύο δυνατότητες.":region==="acute"?"Η γωνία είναι οξεία, άρα το συνημίτονο και η εφαπτομένη είναι θετικά.":"Η γωνία είναι αμβλεία, άρα το συνημίτονο και η εφαπτομένη είναι αρνητικά.";
  return <section aria-labelledby={headingId} className="overflow-hidden rounded-2xl border border-sky-200 bg-gradient-to-br from-sky-50 via-white to-teal-50 dark:border-sky-500/30 dark:from-sky-500/10 dark:via-card dark:to-teal-500/10">
    <div className="flex items-start gap-3 border-b border-sky-200/80 p-4 sm:p-5 dark:border-sky-500/25"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[#1f4e7b] text-white"><Sparkles className="h-5 w-5"/></span><div><div className="text-xs font-extrabold uppercase tracking-widest text-sky-800 dark:text-sky-300">Δυναμικό εργαστήριο</div><h3 id={headingId} className="mt-1 text-xl font-black">Από μία τιμή στις υπόλοιπες</h3><p className="mt-2 text-base leading-relaxed text-muted-foreground">Διάλεξε γνωστό ημίτονο ή συνημίτονο. Η ταυτότητα βρίσκει το τετράγωνο της άλλης τιμής· τα δεδομένα της γωνίας καθορίζουν το πρόσημο.</p></div></div>
    <div className="space-y-5 p-4 sm:p-5"><div className="flex flex-wrap gap-2">{[["sin","Γνωρίζω το ημίτονο"],["cos","Γνωρίζω το συνημίτονο"]].map(([k,label])=><button key={k} type="button" aria-pressed={kind===k} onClick={()=>mode(k)} className={`rounded-xl border px-3 py-2.5 text-base font-bold ${kind===k?"border-sky-800 bg-sky-800 text-white":"border-border bg-background"}`}>{label}</button>)}</div>
      <div className="space-y-4 rounded-xl border border-border bg-background p-4"><div className="flex flex-wrap gap-2">{presets[kind].map(([a,b])=><button key={`${a}/${b}`} type="button" aria-pressed={n*b===a*d} onClick={()=>{setN(a);setD(b);}} className={`rounded-xl border px-3 py-2 text-base font-bold ${n*b===a*d?"border-sky-700 bg-sky-100 dark:bg-sky-500/20":"border-border"}`}>{name[kind]}={b===1?a:`${a}/${b}`}</button>)}</div>
        <div className="flex flex-wrap items-center gap-4"><label className="text-base font-bold">Παρονομαστής <select aria-label="Παρονομαστής γνωστής τιμής" value={d} onChange={e=>{const v=Number(e.target.value);setD(v);setN(Math.max(kind==="sin"?0:-v,Math.min(v,n)));}} className="ml-2 rounded-lg border border-border bg-background px-3 py-2">{[1,2,5,10,13].map(v=><option key={v}>{v}</option>)}</select></label><MathText className="text-xl font-bold" text={`$${command[kind]}\\omega=${model.knownTex}$`}/></div>
        <label className="block text-base font-bold">Αριθμητής: {n} · παρονομαστής: {d}<input aria-label="Αριθμητής γνωστής τιμής" aria-valuetext={`${n} προς ${d}`} type="range" min={kind==="sin"?0:-d} max={d} step="1" value={n} onChange={e=>setN(Number(e.target.value))} className="mt-3 block w-full accent-sky-700"/></label>
        {kind==="sin"&&<fieldset><legend className="mb-2 text-base font-bold">Τι γνωρίζουμε για τη γωνία;</legend><div className="flex flex-wrap gap-2">{[["all","Δεν δίνεται είδος γωνίας"],["acute","Η γωνία είναι οξεία"],["obtuse","Η γωνία είναι αμβλεία"]].map(([r,label])=><button key={r} type="button" aria-pressed={region===r} onClick={()=>setRegion(r)} className={`rounded-xl border px-3 py-2 text-base font-bold ${region===r?"border-teal-700 bg-teal-100 dark:bg-teal-500/20":"border-border"}`}>{label}</button>)}</div></fieldset>}
        <button type="button" onClick={reset} className="inline-flex items-center gap-2 rounded-xl border border-border px-3 py-2 text-base font-bold"><RotateCcw className="h-4 w-4"/>Αρχική περίπτωση</button>
      </div>
      <IdentityDrawing model={model}/><p className="text-base leading-relaxed text-muted-foreground">Η διακεκομμένη ευθεία εκφράζει τη γνωστή συντεταγμένη. Τα αχνά σημεία αποκλείονται από το επιλεγμένο είδος γωνίας.</p>
      <div role="status" className="rounded-xl border border-sky-300 bg-sky-50 p-4 text-base leading-relaxed dark:border-sky-500/30 dark:bg-sky-500/10"><h4 className="text-lg font-black">{status}</h4><p className="mt-2">{reason}</p></div>
      <div className="space-y-3 rounded-xl border border-border bg-background p-4 text-lg"><p className="text-base font-bold">1. Βρίσκουμε το τετράγωνο της άλλης τιμής</p><MathText className="block overflow-x-auto" text={"$\\sin^2\\omega+\\cos^2\\omega=1$"}/><MathText className="block overflow-x-auto" text={`$${command[other]}^2\\omega=1-\\left(${model.knownTex}\\right)^2=${model.remainingSquaredTex}$`}/><MathText className="block overflow-x-auto" text={`$${kind==="sin"?"|\\cos\\omega|":"\\sin\\omega"}=\\sqrt{${model.remainingSquaredTex}}=${model.rootTex}$`}/><p className="text-base leading-relaxed text-muted-foreground">Η ρίζα δίνει μη αρνητικό μέτρο. {kind==="sin"?"Το πρόσημο του συνημιτόνου εξαρτάται από τη θέση στον κύκλο.":"Το ημίτονο είναι μη αρνητικό στο επάνω ημικύκλιο."}</p></div>
      <div className="grid gap-3 md:grid-cols-2">{model.solutions.map(p=><div key={p.index} className="space-y-3 rounded-xl border border-border bg-background p-4"><h4 className="text-lg font-black">{pointName(p)}</h4><MathText className="block text-lg" text={`$\\sin\\omega=${p.tex.sin},\\quad\\cos\\omega=${p.tex.cos}$`}/>{p.tangent===null?<p className="text-base font-bold">Η εφαπτομένη δεν ορίζεται: συνω=0.</p>:<MathText className="block overflow-x-auto text-lg" text={`$\\tan\\omega=\\frac{\\sin\\omega}{\\cos\\omega}=${p.tex.tan}$`}/>}</div>)}</div>
      <div className="space-y-3 rounded-xl border border-teal-200 bg-background p-4 dark:border-teal-500/30"><p className="text-base font-bold">2. Ελέγχουμε την ταυτότητα με ακριβείς τιμές</p><div className="flex h-6 overflow-hidden rounded-full border border-border" role="img" aria-label={`Το τετράγωνο της γνωστής τιμής είναι ${decimal(model.known**2)} και της άλλης ${decimal(1-model.known**2)}. Το άθροισμα είναι 1.`}><div className="bg-sky-700" style={{width:`${100*model.known**2}%`}}/><div className="bg-teal-600" style={{width:`${100*(1-model.known**2)}%`}}/></div><p className="text-base text-muted-foreground">Μπλε: τετράγωνο γνωστής τιμής · πράσινο: τετράγωνο άλλης τιμής</p><MathText className="block text-lg" text={`$${model.knownSquaredTex}+${model.remainingSquaredTex}=1$`}/><p className="text-base leading-relaxed text-muted-foreground">Η ταυτότητα ελέγχει τα τετράγωνα. Ελέγχουμε επιπλέον το πρόσημο και αν επιτρέπεται η διαίρεση με το συνημίτονο.</p></div>
    </div>
  </section>;
}
